let record=null,scope='',loaded=false;const slot='feedback:new',form=el('form'),label=el('label','내용'),input=el('textarea'),hint=el('p','관리자만 확인합니다. 비밀번호·연락처 등 개인정보는 적지 마세요. 별도 답변 기능은 없습니다.'),storage=el('p'),count=el('small'),button=el('button','피드백 보내기'),discard=el('button','초안 삭제'),status=el('p');form.className='feedback112';input.id='feedback112';input.rows=5;input.maxLength=1000;input.required=true;input.placeholder='장소와 발생한 상황을 알려 주세요.';label.htmlFor=input.id;hint.id='feedbackPrivacy112';input.setAttribute('aria-describedby',hint.id);status.setAttribute('role','status');status.setAttribute('aria-live','polite');button.className='primary';button.type='submit';discard.type='button';
